"""Explain signed wrap, memory-order scope and atomic table metadata."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1569': ('끝이 정해진 숫자판은 무한히 큰 수를 적을 수 없어요. 마지막 다음에 처음으로 돌아가는 규칙과 마지막에서 멈추는 규칙도 서로 달라요.', '정수 범위를 도는 wrap과 자료 수명 보호를 구별합니다.', '설명용 4비트 부호 있는 숫자판을 -8부터 7까지 그리세요. wrap 규칙에서 7+1은 -8, -8-1은 7로 이어진다고 표시하세요. 실제 atomic_t가 4비트라는 뜻은 아니에요.', ['signed는 양수뿐 아니라 음수도 담는 정수라는 뜻이에요. 커널의 atomic_t·atomic_long_t·atomic64_t는 각각 int·long·s64를 사용해요. 각 칸에는 정해진 비트 수가 있어 표현 범위도 정해져 있어요.', 'overflow는 계산한 값이 그 표현 범위를 넘어가는 일이에요. wrap은 비트 폭에 맞춰 범위 반대쪽으로 돌아가는 규칙이에요. 설명용 4비트 부호 있는 정수에서는 최대 7에 1을 더하면 최소 -8로 돌아가는 식이에요.', '이 커널 문서는 -fno-strict-overflow라는 빌드 옵션이 -fwrapv를 함의한다고 설명해요. 빌드 옵션은 C 코드를 기계 코드로 바꿀 때 주는 설정이에요. 문서는 그 설정으로 부호 있는 범위 초과를 2의 보수 방식의 wrap으로 정의한다고 명시해요.', '2의 보수는 정해진 비트 안에서 음수를 표현하는 방식이에요. 여기서는 큰 끝값에서 1을 더했을 때 반대쪽 값이 될 수 있다는 점을 먼저 이해하세요. 이 설명을 아무 설정도 없는 모든 C 프로그램에 그대로 적용하면 안 돼요.', '포화는 범위를 계속 돌아가게 두지 않고 정해진 상태에 붙잡아 두는 다른 방식이에요. refcount_t는 자료를 사용하는 참조 수를 관리하며 포화 같은 보호 규칙을 갖는 전용 도구예요. 일반 atomic의 wrap이 이런 수명 보호와 같은 기능은 아니에요.', '자료 수명은 자료를 만든 뒤 언제까지 사용해도 되는지를 뜻해요. 숫자 계산이 원자적이어도 범위를 돌아 0이 되는 일을 사용 종료로 착각하면 문제가 생겨요. 숫자의 정상 범위와 자료를 지울 조건은 따로 설계해야 해요. 이 그림은 계산 규칙의 설명이며 실제 컴파일러 실행 검증은 아니에요.'], [('이 커널 문서는 부호 있는 정수의 wrap을 어떤 설정과 연결하나요?', ['모든 C 프로그램에서 아무 설정 없이 똑같이 보장된다고 해요', '-fno-strict-overflow가 함의하는 -fwrapv와 연결해요'], '정답은 두 번째예요. 문서는 빌드 옵션을 근거로 규칙을 설명해요. 정해진 커널의 약속을 모든 C 환경의 약속으로 넓히면 안 돼요.'), ('숫자가 범위를 돌아가는 wrap은 참조 수의 포화·수명 보호와 같나요?', ['아니요. 계산 규칙과 자료를 안전하게 유지하는 규칙은 달라요', '네. 모든 atomic 숫자판이 자료 해제 오류를 자동으로 막아요'], '정답은 첫 번째예요. 범위 끝을 돌아간다는 사실만으로 자료가 아직 사용 중인지 알 수 없어요. 원자성, 범위 초과, 자료 수명을 따로 살펴야 해요.')]), 'os1570': ('작업의 “읽기” 뒤에 표지판을 두는 것과 “쓰기까지 끝난 작업” 뒤에 표지판을 두는 것은 범위가 달라요. 비슷해 보이는 순서 도구도 어느 부분을 묶는지 확인해야 해요.', 'acquire RMW와 after_atomic의 쓰기 순서 차이를 이해합니다.', 'RMW를 읽기 R → 계산 M → 쓰기 W로 그리세요. 뒤의 다른 주소 쓰기를 X라고 적고, after_atomic은 W와 X 사이의 순서도 묶는다고 표시하세요.', ['RMW는 값을 읽고 계산해서 쓰는 원자 연산이에요. acquire RMW는 그중 읽기 R에 acquire 순서 약속을 줘요. R 이후 접근을 R보다 앞으로 보내지 않는 약속을 전체 W 이후 접근의 약속으로 바꾸어 읽으면 안 돼요.', 'smp_mb__after_atomic은 RMW 뒤에 붙여 순서를 보강하는 도구예요. 문서의 예에서는 원자 증가의 쓰기 W도 그 뒤에 있는 다른 주소 쓰기보다 앞서도록 묶어요. 이 부분에서 acquire만 있는 RMW보다 더 강한 약속이에요.', '문서에는 y를 원자적으로 늘린 뒤 x에 1을 쓰는 CPU와, x를 읽고 읽기 장벽을 거쳐 y를 읽는 CPU가 나와요. after_atomic이 있으면 독자가 x=1을 보고도 y의 이전 값 0을 보는 결과는 허용되지 않는다고 설명해요.', '증가를 acquire 형태로 바꾸는 것만으로 같은 약속을 얻지는 못해요. 문서는 LL.acquire로 y를 읽고, x에 1을 쓴 뒤, 나중에 SC로 y를 저장하는 개념 순서를 보여 줘요. 독자는 사이에 x=1·y=0을 볼 수 있어 두 경우의 차이가 드러나요.', 'LL과 SC는 일부 CPU가 원자 연산을 만드는 읽기·조건부 저장 명령이에요. 이 예시에서 중요한 것은 acquire가 읽기 부분에 붙는다는 점이에요. 원자 연산의 중간값을 y에서 본다는 뜻이 아니라, 다른 주소 x의 쓰기와 y의 쓰기 순서가 다르다는 뜻이에요.', 'litmus는 이런 가능한 관찰 결과를 따져 보는 작은 동시 실행 예제예요. LKMM은 Linux 커널의 메모리 순서 모델이고 herd는 모델에 따라 예제를 분석하는 도구예요. 여기서는 문서 예시를 읽어 대조해요. 문서를 읽거나 숫자 예제를 계산했다고 herd를 실제 실행한 것은 아니에요.'], [('RMW 뒤의 after_atomic을 acquire RMW로 언제나 바꿔도 같은 순서 보장인가요?', ['네. 두 도구가 모든 주소 접근에 주는 약속은 같아요', '아니요. RMW의 쓰기 부분과 뒤 접근을 묶는 범위가 달라요'], '정답은 두 번째예요. 문서의 after 장벽은 W도 뒤 쓰기보다 앞서도록 묶어요. acquire는 R에 붙는 약속이므로 그 차이를 없애서 읽으면 안 돼요.'), ('문서의 작은 동시 실행 예제를 읽어 비교하면 herd 도구도 실행한 것인가요?', ['아니요. 문서 대조와 도구 실행은 별도예요', '네. wrapper의 숫자가 맞으면 모든 LKMM 실행도 검증한 셈이에요'], '정답은 첫 번째예요. 문서가 어떤 결과를 허용하는지 읽은 것과 도구로 그 모델을 실행한 것은 다른 증거예요. 계산 결과 검사도 메모리 순서 전체를 검증하지는 못해요.')]), 'os1571': ('작업 순서가 중요한 설명서를 번역한다고 해 봅시다. 번역 과정에서도 필요한 순서를 지키고, 실제로 일을 하는 쪽에서도 그 순서를 지켜야 해요.', '컴파일러와 CPU 양쪽의 순서 약속, 같은 의미와 같은 성능의 차이를 이해합니다.', 'C 코드 → 컴파일러 → 기계 코드 → CPU의 화살표를 그리세요. 컴파일러와 CPU 아래에 각각 “필요한 접근 순서 지키기”라고 적으세요.', ['컴파일러는 C 코드를 CPU가 실행할 기계 코드로 바꾸는 프로그램이에요. 결과를 빠르게 만들려고 허용된 범위 안에서 작업을 옮기기도 해요. 그래서 소스에 적힌 줄 순서만 보고 실제 메모리 접근 순서를 모두 판단할 수는 없어요.', 'CPU도 자신의 실행 방식에 따라 다른 CPU에 보이는 메모리 접근 순서가 달라질 수 있어요. 따라서 컴파일 단계의 제약과 CPU 메모리 순서의 약속을 함께 생각해야 해요.', 'compiler barrier는 컴파일러가 메모리 접근을 부적절하게 옮기지 못하게 하는 제약이에요. 문서는 full ordering인 원자 RMW가 이 제약도 포함해야 한다고 명시해요. CPU 순서만 강하고 컴파일러는 자유롭게 옮겨도 된다는 뜻이 아니에요.', 'full ordering은 원자 연산의 앞뒤 접근을 함께 묶는 약속이에요. 문서는 full atomic_fetch_add를 before_atomic → relaxed fetch_add → after_atomic과 같은 순서 계약으로 설명해요. 세 단계 표현은 그 약속을 이해하는 데 도움이 돼요.', '같은 계약이라는 말은 같은 명령 수나 같은 속도라는 뜻이 아니에요. CPU에 맞게 만든 full 연산 하나가 도우미를 조합한 형태보다 효율적일 수도 있어요. 반대로 어느 쪽이 얼마나 빠른지는 실제 구현과 실행 조건을 봐야 해요.', '그러므로 이름이 길다거나 함수 호출이 많아 보인다는 이유로 순서 약속을 빼면 안 돼요. 필요한 규칙을 먼저 선택하고 성능은 대상 환경에서 측정해요. 이 수업은 원문의 의미를 비교하며 모든 CPU의 속도가 같다고 주장하지 않아요.'], [('full ordering인 RMW는 문서상 컴파일러가 접근을 옮기는 것에 대한 제약도 포함하나요?', ['아니요. CPU만 순서를 지키면 컴파일러는 마음대로 옮겨도 돼요', '네. compiler barrier도 포함해야 해요'], '정답은 두 번째예요. 코드 번역 과정과 CPU 실행 양쪽이 필요한 순서를 지켜야 해요. 문서는 full ordered atomic이 compiler barrier도 함의해야 한다고 명시해요.'), ('full fetch_add와 앞뒤 장벽을 둔 relaxed 조합의 계약이 같으면 속도도 언제나 같나요?', ['아니요. 같은 약속을 더 효율적인 명령으로 구현할 수도 있어요', '네. 모든 CPU에서 명령 수와 비용까지 같아요'], '정답은 첫 번째예요. 무엇을 보장하는지와 어떤 명령으로 얼마나 빨리 실행하는지는 다른 질문이에요. 문서도 full 연산이 더 효율적일 수 있다고 설명해요.')]), 'os1572': ('명단에 “이 사람에게는 이름표, 출석표, 안내표를 만들어 주세요”라고 짧은 표시를 적을 수 있어요. 원자 API의 표도 문자 몇 개로 만들 함수의 종류를 알려 줘요.', '생성 명세의 문자 분류와 쉘 성공 상태 0을 이해합니다.', 'add | vRF | i v를 세 칸으로 나누세요. 가운데 v는 반환 없음, R은 새 값 반환, F는 이전 값 반환이라고 풀어 적으세요.', ['atomics.tbl은 생성할 원자 함수의 규칙을 적은 표예요. 한 행은 이름, meta, 인자 목록으로 나뉘어요. meta는 어떤 종류를 만들지 설명하는 보조 정보예요. 표 자체가 숫자 저장 객체를 새로 만드는 것은 아니에요.', 'add의 meta는 vRF예요. v는 값을 반환하지 않는 add, R은 계산 뒤 값을 반환하는 add_return, F는 계산 전 값을 반환하는 fetch_add 계열을 만들라는 표시예요. 한 단어를 외우기보다 문자 세 개를 나눠 보세요.', 'b와 B는 참·거짓을 반환하는 종류, i와 I는 기본 정수형을 반환하는 종류예요. l은 읽기, s는 저장을 나타내요. 대문자 표시는 acquire·release·relaxed 같은 순서 변형과 연결되고, l은 acquire, s는 release라는 별도 규칙이 있어요.', 'meta_in은 주어진 문자 하나가 지정된 문자 모음에 들어 있는지 검사하는 쉘 함수예요. case의 [$2] 패턴이 맞으면 return 0, 맞지 않으면 return 1을 실행해요. 쉘에서는 종료 상태 0이 성공이라는 약속이에요.', 'C의 bool에서는 true를 1로 나타내지만 이 쉘 함수의 성공 상태는 0이에요. 둘은 서로 다른 언어의 다른 약속이에요. 쉘의 return 0을 원자 함수가 숫자판에 0을 저장했다는 뜻으로 읽으면 안 돼요.', '인자 목록에도 v나 i 같은 문자가 나오지만 meta 칸과 뜻이 달라요. 인자 칸 v는 원자 객체의 포인터, i는 기본 정수값이에요. add의 i v는 더할 숫자와 대상 위치를 받는다는 뜻이에요. 같은 글자라도 어느 칸에 있는지 확인하세요.'], [('쉘 함수 meta_in에서 문자가 분류에 맞을 때의 종료 상태는 무엇인가요?', ['C의 true와 같으므로 항상 정수 1이에요', '쉘의 성공 상태인 0이에요'], '정답은 두 번째예요. case가 일치하는 갈래에서 return 0을 실행해요. C bool의 true=1과 쉘 명령의 성공=0을 구별하세요.'), ('표의 add 행에 적힌 meta vRF는 무엇을 뜻하나요?', ['반환 없는 add·새 값 반환 add_return·이전 값 반환 fetch_add 계열이에요', '서로 다른 숫자 저장 객체 세 개를 만들라는 뜻이에요'], '정답은 첫 번째예요. 이 문자는 함수 변형을 고르는 명세예요. 실행 중에 숫자판 세 개를 만드는 명령이 아니에요. 또 인자 칸의 v와 meta 칸의 v는 다른 뜻이에요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_388.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
